::::success[$\mathcal{O}(n^2)$]
首先玩一玩发现贪心非常假，直接考虑 dp。朴素 $\mathcal{O}(n^2)$ 的 dp 是设 $dp_i$ 表示前 $i$ 个位置的最大总长度。转移方程就是：
$$
dp_i=\max(dp_{i-1}, \max\limits_{\substack{j < i \\ y_j \le y_i \\ b_j \le b_i}}(dp_j + i - j))
$$
:::success[code]
```cpp
#include <bits/stdc++.h>
#define int long long
using namespace std;
const int N = 2e6 + 10;
int n, y[N], b[N], dp[N];
signed main(){
//	freopen("red.in", "r", stdin);
//	freopen("red.out", "w", stdout);
	cin.tie(0);
	std::ios::sync_with_stdio(0);
	cin >> n;
	for(int i = 1; i <= n; i++){
		char c;
		cin >> c;
		int d = c - '0';
		y[i] = d / 4 - d % 4 / 2 + y[i - 1];
		b[i] = d / 4 - d % 2 + b[i - 1];
 	}
	for(int i = 1; i <= n; i++){
		dp[i] = dp[i - 1];
		for(int j = 0; j <= i - 1; j++){
			if(y[i] >= y[j] && b[i] >= b[j]) dp[i] = max(dp[i], dp[j] + i - j);
		}
	}
	cout << dp[n] << "\n";
	return 0;
}
/*
10
4336352375
*/

