::::success[$\mathcal{O}(nlogn)$]
我们可以发现如果中间某一段的 $y,b$ 均大于 $0$，那么向左或者右扩展一定是更优的，所以这又双叒叕是一个假的三维偏序，只需要开两组每组 $n$ 棵动态开点的权值线段树就可以了。第一组第 $i$ 棵中 $[l,r]$ 存的是 $y_i = i$ 且 $l \le b_i \le r$ 的 $dp_j - j$ 的最大值，第二组类似。这题既卡时间又卡空间，不能离散化，否则会 TLE。但是所有的 $y_i,b_i$ 都是在一个 $\mathcal{O}(n)$ 的区间内的，所以我们只需要卡一下上下界，并给 $y_i$ 和 $b_i$ 分别加上一些偏移量使其恒为正即可。
:::success[code]
```cpp
#include <bits/stdc++.h>
using namespace std;
const int N = 2e6 + 10, inf = 1e9;
int n, y[N], b[N], tot;
char c[N];
int rty[N], rtb[N], dp[N];
struct Node{
	int ls, rs, mx;
}tr[N * 44];
void pushup(int u){tr[u].mx = max(tr[tr[u].ls].mx, tr[tr[u].rs].mx);}
void modify(int &u, int l, int r, int p, int v){
	if(!u) u = ++tot, tr[u].mx = -inf;
	if(l == r){
		tr[u].mx = max(tr[u].mx, v);
		return;
	}
	int mid = l + r >> 1;
	if(p <= mid) modify(tr[u].ls, l, mid, p, v);
	else modify(tr[u].rs, mid + 1, r, p, v);
	pushup(u);
}
int query(int u, int l, int r, int ql, int qr){
	if(!u || ql > r || qr < l) return -inf;
	if(ql <= l && r <= qr) return tr[u].mx;
	int mid = l + r >> 1;
	int res = -inf;
	if(ql <= mid) res = max(res, query(tr[u].ls, l, mid, ql, qr));
	if(qr > mid) res = max(res, query(tr[u].rs, mid + 1, r, ql, qr));
	return res;
}
signed main(){
//	freopen(".in", "r", stdin);
//	freopen(".out", "w", stdout);
	cin.tie(0);
	std::ios::sync_with_stdio(0);
	cin >> n;
	cin >> c + 1;
	tr[0].mx = -inf;
	int mn1 = 0, mn2 = 0, mx1 = 0, mx2 = 0;
	for(int i = 1; i <= n; i++){
		int d = c[i] - '0';
		y[i] = d / 4 - d % 4 / 2 + y[i - 1];
		b[i] = d / 4 - d % 2 + b[i - 1];	
		mn1 = min(mn1, y[i]), mx1 = max(mx1, y[i]);
		mn2 = min(mn2, b[i]), mx2 = max(mx2, b[i]);
	}
	mn1 = max(1, -mn1 + 1);
	mn2 = max(1, -mn2 + 1);
	mx1 += mn1;
	mx2 += mn2;
	modify(rty[mn1], 1, mx2, mn2, 0);
	modify(rtb[mn2], 1, mx1, mn1, 0);
	for(int i = 1; i <= n; i++){
		int q1 = query(rty[y[i] + mn1], 1, mx2, 1, b[i] + mn2) + i;
		int q2 = query(rtb[b[i] + mn2], 1, mx1, 1, y[i] + mn1) + i;
		dp[i] = max(dp[i - 1], max(q1, q2));
		if(y[i] >= 0 && b[i] >= 0) dp[i] = max(dp[i], i);
		modify(rty[y[i] + mn1], 1, mx2, b[i] + mn2, dp[i] - i);
		modify(rtb[b[i] + mn2], 1, mx1, y[i] + mn1, dp[i] - i);

	}
	cout << dp[n] << "\n";
	return 0;
}
/*
10
4336352375
*/

```
